//! Source-bound finite precision increase after the inherited optimization tables.
//! This is a capacity change, not an exact resource-only optimization.
use crate::circuit::{BitId,Op,OperationType as K,QubitId,RegisterId};
use std::collections::BTreeSet;
const NONE:u64=u64::MAX;
const OLD:&[u8]=include_bytes!("precision_fold_old.bin");
const NEW:&[u8]=include_bytes!("precision_fold_new.bin");
// The next payload bit is source-derived from the original/new builder's exact
// accumulator-wire metadata, whose common prefix is byte-identical.
const EXTENDED_PAYLOAD_Q:u64=907;
fn decode(data:&[u8])->Vec<Op>{assert_eq!(data.len()%56,0);data.chunks_exact(56).map(|b|{let u=|i|u64::from_le_bytes(b[i..i+8].try_into().unwrap());let kind=match u(0){0=>K::Neg,1=>K::Register,2=>K::AppendToRegister,3=>K::BitInvert,4=>K::BitStore0,5=>K::BitStore1,6=>K::X,7=>K::Z,8=>K::CX,9=>K::CZ,10=>K::Swap,11=>K::R,12=>K::Hmr,13=>K::CCX,14=>K::CCZ,15=>K::PushCondition,16=>K::PopCondition,17=>K::DebugPrint,_=>panic!("unknown operation")};let o=Op{kind,q_control2:QubitId(u(8)),q_control1:QubitId(u(16)),q_target:QubitId(u(24)),c_target:BitId(u(32)),c_condition:BitId(u(40)),r_target:RegisterId(u(48))};o.validate();o}).collect()}
fn depth_after(mut depth:usize,o:&Op)->usize{if o.kind==K::PushCondition{depth+=1;}else if o.kind==K::PopCondition{depth=depth.checked_sub(1).expect("unbalanced scope");}depth}
fn local_block(ops:&[Op])->BTreeSet<u64>{let mut depth=0;let written:BTreeSet<_>=ops.iter().filter(|o|[K::Hmr,K::BitStore0,K::BitStore1,K::BitInvert].contains(&o.kind)).map(|o|o.c_target.0).collect();let mut initialized=BTreeSet::new();for o in ops{let reads=o.c_condition.0;if reads!=NONE&&written.contains(&reads){assert!(initialized.contains(&reads),"measurement version reads incoming state");}if [K::Hmr,K::BitStore0,K::BitStore1,K::BitInvert].contains(&o.kind){let ct=o.c_target.0;assert_ne!(ct,NONE);if o.kind==K::BitInvert{assert!(initialized.contains(&ct),"bit invert reads incoming state");}if depth==0&&o.c_condition.0==NONE&&o.kind!=K::BitInvert{initialized.insert(ct);}}depth=depth_after(depth,o);}assert_eq!(depth,0,"region does not close scope");assert!(written.is_subset(&initialized),"conditionally initialized scratch bit");written}
pub fn run(mut ops:Vec<Op>)->Vec<Op>{let old=decode(OLD);let new=decode(NEW);let matches:Vec<_>=ops.windows(old.len()).enumerate().filter(|(_,w)|*w==old.as_slice()).map(|(i,_)|i).collect();assert_eq!(matches.len(),1,"precision region missing, ambiguous, or edited by inherited table");let at=matches[0];let end=at+old.len();let mut depth=0;for(i,o)in ops.iter().enumerate(){if i==at||i==end{assert_eq!(depth,0,"precision region crosses outer scope snapshot");}depth=depth_after(depth,o);}assert_eq!(depth,0);let oldbits=local_block(&old);let newbits=local_block(&new);assert_eq!(oldbits,newbits,"new classical scratch allocation");
// Check version locality. Global reuse of a physical measurement ID is fine:
// no current value may escape before the next unconditional overwrite.
let mut pending=oldbits.clone();let mut depth=0;for o in &ops[end..]{let cc=o.c_condition.0;if pending.contains(&cc){panic!("precision measurement outcome is live outside region");}if o.kind==K::BitInvert&&pending.contains(&o.c_target.0){panic!("precision classical value is live outside region");}if depth==0&&cc==NONE&&[K::Hmr,K::BitStore0,K::BitStore1].contains(&o.kind){pending.remove(&o.c_target.0);}depth=depth_after(depth,o);if pending.is_empty(){break;}}assert!(pending.is_empty(),"scratch value never overwritten before circuit end");
let nq=ops.iter().flat_map(|o|[o.q_control2.0,o.q_control1.0,o.q_target.0]).filter(|&q|q!=NONE).max().unwrap();assert!(new.iter().flat_map(|o|[o.q_control2.0,o.q_control1.0,o.q_target.0]).filter(|&q|q!=NONE).all(|q|q<=nq),"new quantum wire");
let quantum_set=|rows:&[Op]|rows.iter().flat_map(|o|[o.q_control2.0,o.q_control1.0,o.q_target.0]).filter(|&q|q!=NONE).collect::<BTreeSet<_>>();let oldq=quantum_set(&old);let newq=quantum_set(&new);let added:BTreeSet<_>=newq.difference(&oldq).copied().collect();assert!(added.contains(&EXTENDED_PAYLOAD_Q),"precision payload wire mismatch");for q in added.into_iter().filter(|&q|q!=EXTENDED_PAYLOAD_Q){let mut last=None;let mut d=0;for o in &ops[..at]{if [o.q_control2.0,o.q_control1.0,o.q_target.0].contains(&q){last=Some((*o,d));}d=depth_after(d,o);}assert!(last.map_or(true,|(o,d)|d==0&&o.c_condition.0==NONE&&o.q_target.0==q&&[K::R,K::Hmr].contains(&o.kind)),"added precision scratch not universally clean at entry");let mut last=None;let mut d=0;for o in &new{if [o.q_control2.0,o.q_control1.0,o.q_target.0].contains(&q){last=Some((*o,d));}d=depth_after(d,o);}assert!(last.is_some_and(|(o,d)|d==0&&o.c_condition.0==NONE&&o.q_target.0==q&&[K::R,K::Hmr].contains(&o.kind)),"added precision scratch not reset at exit");}
ops.splice(at..end,new);eprintln!("PRECISION_REGION forward_tick=1 precision=57->58 old_ops={} new_ops={} at={} unique=true empty_scope=true classical_versions_local=true existing_tables_retained=true",old.len(),NEW.len()/56,at);ops}

#[cfg(test)]mod tests{use super::*;fn kill()->Op{let mut o=Op::empty();o.kind=K::Hmr;o.q_target=QubitId(0);o.c_target=BitId(1568);o}fn old()->Vec<Op>{let mut x=decode(OLD);x.push(kill());x}
#[test]fn complete_region_positive(){let mut fixture=old();let mut wire=Op::empty();wire.kind=K::X;wire.q_target=QubitId(1233);fixture.extend([wire,wire]);let actual=run(fixture);let mut expected=decode(NEW);expected.push(kill());expected.extend([wire,wire]);assert_eq!(actual,expected);}
#[test]#[should_panic]fn missing_quantum_capacity_rejected(){run(old());}
#[test]#[should_panic]fn dirty_added_scratch_rejected(){let mut x=old();let mut o=Op::empty();o.kind=K::X;o.q_target=QubitId(1205);x.insert(0,o);let mut wire=Op::empty();wire.kind=K::X;wire.q_target=QubitId(1233);x.extend([wire,wire]);run(x);}
#[test]#[should_panic]fn partial_region_rejected(){let mut x=old();x.remove(100);run(x);}
#[test]#[should_panic]fn ambiguous_region_rejected(){let mut x=old();x.extend(old());run(x);}
#[test]#[should_panic]fn outer_scope_rejected(){let mut x=old();let mut p=Op::empty();p.kind=K::PushCondition;p.c_condition=BitId(1);x.insert(0,p);let mut p=Op::empty();p.kind=K::PopCondition;x.push(p);run(x);}
#[test]#[should_panic]fn live_outcome_rejected(){let mut x=old();let mut o=Op::empty();o.kind=K::X;o.q_target=QubitId(0);o.c_condition=BitId(1568);x.insert(x.len()-1,o);run(x);}
#[test]#[should_panic]fn incoming_outcome_rejected(){let mut x=vec![];let mut o=Op::empty();o.kind=K::X;o.q_target=QubitId(0);o.c_condition=BitId(1568);x.push(o);x.push(kill());local_block(&x);}
#[test]#[should_panic]fn snapshot_crossing_rejected(){let mut x=old();let mut p=Op::empty();p.kind=K::PushCondition;p.c_condition=BitId(1568);x.insert(x.len()-1,p);let mut p=Op::empty();p.kind=K::PopCondition;x.push(p);run(x);}
}
